import itertools

def find_sequences_brute_force(max_n, max_val):
    for a_vals in itertools.product(range(max_val), repeat=max_n):
        a = list(a_vals)
        possible = True
        for p in range(max_n - 1):
            idx1 = a[p]
            if idx1 >= max_n:
                possible = False
                break
            idx2 = a[idx1]
            if idx2 >= max_n:
                possible = False
                break
            if a[idx2] != a[p+1] + 1:
                possible = False
                break
        if possible:
            print(a)

